questions.uml_mutation:
class ParkingFloor {
    -String floorId
}
class ParkingSlot {
    -String slotId
    -boolean isAvailable
}
ParkingFloor "1" *-- "*" ParkingSlot : contains_slots

class Vehicle {
    -String licensePlate
}
ParkingSlot o-- Vehicle : currently_parks

class Vehicle {
    <<abstract>>
    -String licensePlate
    +getRequiredSpotType() : SpotType
}
class Car {
    +getRequiredSpotType() : SpotType
}
class Truck {
    +getRequiredSpotType() : SpotType
}
Vehicle <|-- Car
Vehicle <|-- Truck

class PricingStrategy {
    <<interface>>
    +calculateFee(ticket: ParkingTicket) : double
}
class HourlyPricing {
    +calculateFee(ticket: ParkingTicket) : double
}
PricingStrategy <|.. HourlyPricing

class CheckoutProcessor {
    -PricingStrategy strategy
    +processPayment(ticket: ParkingTicket)
}
CheckoutProcessor --> PricingStrategy : utilizes

class FloorObserver {
    <<interface>>
    +onFloorFull(floorId: String)
}
class DisplayBoard {
    +onFloorFull(floorId: String)
}
FloorObserver <|.. DisplayBoard
ParkingFloor --> FloorObserver : notifies

class EntryPanel {
    -String panelId
}
class ExitPanel {
    -String panelId
}
ParkingLotController "1" o-- "*" EntryPanel : coordinates
ParkingLotController "1" o-- "*" ExitPanel : coordinates
ParkingLotController "1" *-- "*" ParkingFloor : manages

class ParkingLotController {
    +assignSlot(v: Vehicle) : ParkingSlot
    +processEntry(v: Vehicle, panelId: String) : ParkingTicket
    +processExit(ticket: ParkingTicket, panelId: String) : Receipt
}
